Path('/output/fit_utils.py').write_text('''import numpy as np
z=np.load('/output/data.npz');x=z['x'];p=z['p'];n=128
q=p[:,5:].reshape(-1,16);s=x[:,:19].ravel();tt=np.tile(np.arange(5,24),n);seq=np.repeat(np.arange(n),19)
perm=np.array([13,12,11,2,15,6,3,4,9,10,1,7,5,14,0,8]);target=perm[s]
mask=np.arange(16)[None,:]!=target[:,None];peak=q[np.arange(len(q)),target]
Yp=np.log(peak/(1-peak));Yo=np.log(q);Yo=(Yo-(Yo*mask).sum(1,keepdims=True)/15)*mask
trseq=np.load('/output/split.npz')['trseq'];tr=np.isin(seq,trseq);te=~tr

def design(lags=(),inter=False,pairs=(),matches=False):
 fs=[np.eye(16)[s],np.eye(19)[tt-5]]
 vs={}
 for l in set(lags)|set(pairs)|set([1,2,3,4,6,9] if matches else []):
  v=np.full((n,19),16,int)
  for t in range(5,24):
   if t>=l:v[:,t-5]=x[:,t-l]
  vs[l]=v.ravel()
 for l in lags:fs.append(np.eye(17)[vs[l]])
 if inter:fs.append(np.eye(304)[s*19+tt-5])
 for l in pairs:fs.append(np.eye(272)[s*17+vs[l]])
 if matches:
  for l in [1,2,3,4,6,9]:fs.append(np.stack([vs[l]==s,vs[l]==target],1).astype(float))
 return np.concatenate(fs,1)

def fit(D,Y,train,lam,excluded=None,penalty=None):
 reg=np.eye(D.shape[1])*lam
 if penalty is not None:reg*=penalty
 if Y.ndim==1:return np.linalg.solve(D[train].T@D[train]+reg,D[train].T@Y[train])
 coef=np.zeros((D.shape[1],Y.shape[1]))
 for j in range(Y.shape[1]):
  m=train if excluded is None else train&excluded[:,j]
  coef[:,j]=np.linalg.solve(D[m].T@D[m]+reg,D[m].T@Y[m,j])
 return coef

def predict(Dp,cp,Do,co):
 peak=1/(1+np.exp(-Dp@cp));o=Do@co;o-=o.max(1,keepdims=True);o=np.exp(o)*mask;o/=o.sum(1,keepdims=True);o*=1-peak[:,None];o[np.arange(len(o)),target]=peak
 return o

def metrics(P,test=te):
 kl=np.mean(np.sum(q[test]*np.log(q[test]/P[test]),1));rmse=np.sqrt(((q[test]-P[test])**2).mean())
 pk=P[np.arange(len(P)),target];bkl=np.mean(peak[test]*np.log(peak[test]/pk[test])+(1-peak[test])*np.log((1-peak[test])/(1-pk[test])))
 return [float(kl),float(rmse),float(bkl)]
''')
